CREATE OR REPLACE FUNCTION jetnity_prod_import_scheduler.tick_v1()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET statement_timeout TO '10s'
 SET lock_timeout TO '2s'
AS $function$
DECLARE
  moment timestamptz:=clock_timestamp();
  control jetnity_prod_import_scheduler.state_v1%ROWTYPE;
  cycle jetnity_prod_import_scheduler.cycles_v1%ROWTYPE;
  dispatch jetnity_prod_import_scheduler.dispatches_v1%ROWTYPE;
  reply record;
  result jsonb;
  signing_key text;
  actual_mac text;
  expected_mac text;
  mac_count integer;
  response_status text;
  amount integer;
  request_id bigint;
  timestamp_ms text;
  request_body jsonb;
  start_left integer;
  operation_left integer;
  quota jsonb;
  response_verified boolean:=false;
  target_url constant text:='https://jetnity.com/api/internal/readiness/ch-de-prod-refresh';
  target_path constant text:='/api/internal/readiness/ch-de-prod-refresh';
BEGIN
  IF current_user<>'postgres' OR session_user<>'postgres' OR current_database()<>'postgres' THEN
    RAISE EXCEPTION 'Production scheduler operator only';
  END IF;
  IF NOT pg_try_advisory_xact_lock(771106,32) THEN RETURN 'busy'; END IF;
  SELECT * INTO STRICT control FROM jetnity_prod_import_scheduler.state_v1 WHERE singleton FOR UPDATE;
  IF NOT control.enabled THEN RETURN 'disabled'; END IF;
  -- Unchanged normal BG1 remains authoritative; this sender never runs an audit.
  IF NOT EXISTS(SELECT 1 FROM official_v3_guard_private.state_v1
    WHERE singleton AND incident_generation=resumed_generation AND valid_until>moment
      AND last_proof_started IS NOT NULL AND last_finished>=last_proof_started) THEN
    UPDATE jetnity_prod_import_scheduler.state_v1 SET status='guard_not_current' WHERE singleton;
    RETURN 'guard_not_current';
  END IF;
  IF to_regprocedure('official_v3_guard_private.ch_de_quota_v2()') IS NULL THEN
    UPDATE jetnity_prod_import_scheduler.state_v1 SET status='quota_state_unavailable',observed_at=moment WHERE singleton;
    RETURN 'quota_state_unavailable';
  END IF;
  -- The separately installed successor owns rolling admission and terminal
  -- reserve. Never derive a daily allowance by resetting lifetime counters.
  quota:=official_v3_guard_private.ch_de_quota_v2();
  IF quota->>'model' IS DISTINCT FROM 'rolling_24h_v2' OR quota->'clock_ok' IS DISTINCT FROM 'true'::jsonb
    OR jsonb_typeof(quota->'remaining_starts') IS DISTINCT FROM 'number'
    OR jsonb_typeof(quota->'remaining_operations') IS DISTINCT FROM 'number'
    OR (quota->>'remaining_starts') !~ '^[0-9]{1,2}$'
    OR (quota->>'remaining_operations') !~ '^[0-9]{1,3}$' THEN
    UPDATE jetnity_prod_import_scheduler.state_v1 SET status='quota_state_unavailable',observed_at=moment WHERE singleton;
    RETURN 'quota_state_unavailable';
  END IF;
  start_left:=(quota->>'remaining_starts')::integer;
  operation_left:=(quota->>'remaining_operations')::integer;
  IF start_left>64 OR operation_left>256 THEN
    UPDATE jetnity_prod_import_scheduler.state_v1 SET status='quota_state_unavailable',observed_at=moment WHERE singleton;
    RETURN 'quota_state_unavailable';
  END IF;
  UPDATE jetnity_prod_import_scheduler.state_v1 SET observed_at=moment,
    remaining_starts=start_left,remaining_operations=operation_left WHERE singleton;
  SELECT decrypted_secret INTO STRICT signing_key FROM vault.decrypted_secrets
    WHERE name='jetnity_prod_import_cron_v1';
  IF signing_key IS NULL OR length(signing_key) NOT BETWEEN 32 AND 256 OR signing_key !~ '^[A-Za-z0-9_-]+$' THEN
    RAISE EXCEPTION 'scheduler signing configuration unavailable';
  END IF;
  SELECT * INTO cycle FROM jetnity_prod_import_scheduler.cycles_v1 WHERE state='active' FOR UPDATE;
  IF NOT FOUND THEN
    IF EXISTS(SELECT 1 FROM jetnity_prod_import_scheduler.cycles_v1 WHERE state='blocked') THEN
      UPDATE jetnity_prod_import_scheduler.state_v1 SET status='operator_review_required' WHERE singleton;
      RETURN 'operator_review_required';
    END IF;
    IF control.next_due_at>moment THEN
      UPDATE jetnity_prod_import_scheduler.state_v1 SET status='not_due' WHERE singleton;
      RETURN 'not_due';
    END IF;
    -- Reserve the existing attempt/operation allowance. Never reset or increase it.
    IF start_left<4 OR operation_left<16 THEN
      UPDATE jetnity_prod_import_scheduler.state_v1 SET status='daily_capacity_low' WHERE singleton;
      RETURN 'daily_capacity_low';
    END IF;
    INSERT INTO jetnity_prod_import_scheduler.cycles_v1(operation_id,lease_id)
      VALUES('op3_'||replace(gen_random_uuid()::text,'-',''),'lease3_'||replace(gen_random_uuid()::text,'-',''))
      RETURNING * INTO cycle;
  END IF;
  SELECT * INTO dispatch FROM jetnity_prod_import_scheduler.dispatches_v1
    WHERE cycle_id=cycle.id AND processed_at IS NULL ORDER BY id DESC LIMIT 1 FOR UPDATE;
  IF FOUND THEN
    SELECT * INTO reply FROM net._http_response WHERE id=dispatch.net_request_id;
    IF NOT FOUND AND moment<dispatch.dispatched_at+interval '90 seconds' THEN
      UPDATE jetnity_prod_import_scheduler.state_v1 SET status='awaiting_response' WHERE singleton;
      RETURN 'awaiting_response';
    END IF;
    response_status:='response_unconfirmed';
    IF FOUND AND reply.timed_out IS NOT TRUE AND reply.error_msg IS NULL AND reply.status_code BETWEEN 200 AND 599
      AND reply.content IS NOT NULL AND octet_length(reply.content)<=1024
      AND moment<=dispatch.dispatched_at+interval '150 seconds' THEN
      BEGIN
        result:=reply.content::jsonb;
        amount:=(result->>'published')::integer;
        response_status:=result->>'status';
        SELECT count(*),min(value) INTO mac_count,actual_mac FROM jsonb_each_text(reply.headers)
          WHERE lower(key)='x-jetnity-prod-import-mac';
        expected_mac:=encode(extensions.hmac(concat_ws(E'\n','jetnity-prod-import-response-v1','POST',target_path,
          dispatch.signed_at_ms,'2',dispatch.phase,cycle.operation_id,cycle.lease_id,'1',reply.status_code::text,response_status,amount::text),
          signing_key,'sha256'),'hex');
        response_verified:=result=jsonb_build_object('schema',1,'status',response_status,'published',amount)
          AND response_status IN ('queued','published','complete','exhausted','busy','not_approved','unavailable','access_required','request_refused','unresolved')
          AND amount BETWEEN 0 AND 32 AND (response_status IN ('published','unresolved') OR amount=0)
          AND mac_count=1 AND actual_mac ~ '^[a-f0-9]{64}$' AND actual_mac=expected_mac
          AND dispatch.phase=cycle.phase;
      EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN
        response_verified:=false;
      END;
    END IF;
    IF response_verified IS NOT TRUE THEN response_status:='response_unconfirmed'; END IF;
    UPDATE jetnity_prod_import_scheduler.dispatches_v1 SET processed_at=moment,
      http_status=CASE WHEN reply.id IS NOT NULL THEN reply.status_code ELSE NULL END,outcome=response_status
      WHERE id=dispatch.id;
    IF response_verified AND reply.status_code=200 AND response_status='queued' AND cycle.phase='start' THEN
      UPDATE jetnity_prod_import_scheduler.cycles_v1 SET phase='resume',phase_attempts=0,last_status='queued'
        WHERE id=cycle.id RETURNING * INTO cycle;
    ELSIF response_verified AND reply.status_code=200 AND response_status='published' AND amount>0 AND cycle.phase='resume' THEN
      UPDATE jetnity_prod_import_scheduler.cycles_v1 SET state='published',published=amount,finished_at=moment,last_status='published'
        WHERE id=cycle.id;
      -- Preparation can precede publication ACK. Anchor to original request time.
      UPDATE jetnity_prod_import_scheduler.state_v1 SET next_due_at=cycle.created_at+interval '40 minutes',status='published' WHERE singleton;
      RETURN 'published';
    ELSE
      UPDATE jetnity_prod_import_scheduler.cycles_v1 SET last_status=response_status WHERE id=cycle.id;
    END IF;
    IF response_verified AND response_status IN ('exhausted','not_approved','access_required','request_refused') THEN
      UPDATE jetnity_prod_import_scheduler.cycles_v1 SET state='blocked',finished_at=moment WHERE id=cycle.id;
      UPDATE jetnity_prod_import_scheduler.state_v1 SET status='operator_review_required' WHERE singleton;
      RETURN 'operator_review_required';
    END IF;
  END IF;
  IF cycle.phase_attempts>=8 OR moment>=cycle.created_at+interval '25 minutes' THEN
    UPDATE jetnity_prod_import_scheduler.cycles_v1 SET state='blocked',finished_at=moment,last_status='retry_budget_exhausted' WHERE id=cycle.id;
    UPDATE jetnity_prod_import_scheduler.state_v1 SET status='operator_review_required' WHERE singleton;
    RETURN 'operator_review_required';
  END IF;
  -- Identifiers and phase are durable before pg_net can send after COMMIT.
  timestamp_ms:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint::text;
  request_body:=jsonb_build_object('schema',2,'mode',cycle.phase,'operationId',cycle.operation_id,'leaseId',cycle.lease_id);
  expected_mac:=encode(extensions.hmac(concat_ws(E'\n','jetnity-prod-import-v1','POST',target_path,timestamp_ms,'2',
    cycle.phase,cycle.operation_id,cycle.lease_id),signing_key,'sha256'),'hex');
  request_id:=net.http_post(url:=target_url,body:=request_body,params:='{}'::jsonb,
    headers:=jsonb_build_object('Content-Type','application/json','Authorization','HMAC-SHA256 '||expected_mac,
      'X-Jetnity-Prod-Import-Time',timestamp_ms),timeout_milliseconds:=65000);
  INSERT INTO jetnity_prod_import_scheduler.dispatches_v1(cycle_id,phase,signed_at_ms,net_request_id)
    VALUES(cycle.id,cycle.phase,timestamp_ms,request_id);
  UPDATE jetnity_prod_import_scheduler.cycles_v1 SET phase_attempts=phase_attempts+1 WHERE id=cycle.id;
  UPDATE jetnity_prod_import_scheduler.state_v1 SET status='dispatched_'||cycle.phase WHERE singleton;
  RETURN 'dispatched_'||cycle.phase;
END $function$

CREATE OR REPLACE FUNCTION net._await_response(request_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare
    rec net._http_response;
begin
    while rec is null loop
        select *
        into rec
        from net._http_response
        where id = request_id;

        if rec is null then
            -- Wait 50 ms before checking again
            perform pg_sleep(0.05);
        end if;
    end loop;

    return true;
end;
$function$

CREATE OR REPLACE FUNCTION net._http_collect_response(request_id bigint, async boolean DEFAULT true)
 RETURNS net.http_response_result
 LANGUAGE plpgsql
AS $function$
declare
    rec net._http_response;
    req_exists boolean;
begin

    if not async then
        perform net._await_response(request_id);
    end if;

    select *
    into rec
    from net._http_response
    where id = request_id;

    if rec is null or rec.error_msg is not null then
        -- The request is either still processing or the request_id provided does not exist

        -- TODO: request in progress is indistinguishable from request that doesn't exist

        -- No request matching request_id found
        return (
            'ERROR',
            coalesce(rec.error_msg, 'request matching request_id not found'),
            null
        )::net.http_response_result;

    end if;

    -- Return a valid, populated http_response_result
    return (
        'SUCCESS',
        'ok',
        (
            rec.status_code,
            rec.headers,
            rec.content
        )::net.http_response
    )::net.http_response_result;
end;
$function$

CREATE OR REPLACE FUNCTION net.http_collect_response(request_id bigint, async boolean DEFAULT true)
 RETURNS net.http_response_result
 LANGUAGE plpgsql
AS $function$
begin
  raise notice 'The net.http_collect_response function is deprecated.';
  select net._http_collect_response(request_id, async);
end;
$function$

CREATE OR REPLACE FUNCTION official_v3_at_production_private.enqueue_v1()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE src record; b bigint; n integer:=0; started timestamptz;
BEGIN
 IF session_user<>'postgres' OR current_user<>session_user
 OR public.official_v3_guard_alarm_status_v1()->>'status'<>'current'
 THEN RETURN 0; END IF;
 IF NOT pg_try_advisory_xact_lock(771112,1) THEN RETURN 0; END IF;
 IF (SELECT max(started_at) FROM official_v3_at_production_private.watch_batches_v1)
 >clock_timestamp()-interval '50 minutes' THEN RETURN 0; END IF;
 started:=clock_timestamp();
 INSERT INTO official_v3_at_production_private.watch_batches_v1(started_at)
 VALUES(started) RETURNING batch_id INTO b;
 FOR src IN SELECT source_id,official_url FROM official_v3_at_production_private.source_pins_v1 ORDER BY source_id LOOP
   INSERT INTO official_v3_at_production_private.watch_requests_v1
     (batch_id,source_id,request_id,requested_at)
   VALUES(b,src.source_id,net.http_get(src.official_url,'{}'::jsonb,
      '{"accept":"text/html"}'::jsonb,15000),started);
   n:=n+1;
 END LOOP;
 IF n<>3 THEN RAISE EXCEPTION 'AT_PRODUCTION_INCOMPLETE_SOURCE_REQUEST' USING ERRCODE='P7979'; END IF;
 RETURN n;
END $function$
